//! The repositories of the "audit_log" table. Repositories decide nothing.

use async_trait::async_trait;
use crate::audit_log::table as table;
use crate::audit_log::entity::AuditLog;
use crate::common::CursorPage;
use crate::database::Db;
use crate::errors::DomainError;
use sea_orm::{ColumnTrait, Condition, EntityTrait, QueryFilter, QueryOrder, QuerySelect};
use std::cmp::Ordering;
use std::sync::{Arc, Mutex};

/// Where audit_log rows are kept. Services depend only on this trait.
#[async_trait]
pub trait AuditLogRepository: Send + Sync {
    /// At most limit rows after the key after (None for the first page), by primary key, and the key to read the next page from.
    async fn list(&self, after: Option<(chrono::DateTime<chrono::FixedOffset>, String)>, limit: u64) -> Result<CursorPage<AuditLog, (chrono::DateTime<chrono::FixedOffset>, String)>, DomainError>;
}

/// Keeps audit_log rows in the database, through SeaORM: on the connection of the unit of work, or in its transaction.
pub struct SqlAuditLogRepository<'a> {
    db: &'a Db,
}

impl<'a> SqlAuditLogRepository<'a> {
    pub fn new(db: &'a Db) -> Self {
        Self { db }
    }
}

#[async_trait]
impl AuditLogRepository for SqlAuditLogRepository<'_> {
    async fn list(&self, after: Option<(chrono::DateTime<chrono::FixedOffset>, String)>, limit: u64) -> Result<CursorPage<AuditLog, (chrono::DateTime<chrono::FixedOffset>, String)>, DomainError> {
        let db = self.db.executor();
        let mut query = table::Entity::find();
        if let Some(after) = after {
            let (after0, after1) = after;
            query = query.filter(Condition::any().add(table::Column::At.gt(after0.clone())).add(Condition::all().add(table::Column::At.eq(after0.clone())).add(table::Column::Message.gt(after1.clone()))));
        }
        let rows = query.order_by_asc(table::Column::At).order_by_asc(table::Column::Message).limit(limit + 1).all(&db).await?;
        let more = rows.len() as u64 > limit;
        let items: Vec<AuditLog> = rows.into_iter().take(limit as usize).map(to_entity).collect();
        let next = if more { items.last().map(|last| (last.at.expect("at is set"), last.message.clone().expect("message is set"))) } else { None };
        Ok(CursorPage { items, next })
    }
}

fn to_entity(model: table::Model) -> AuditLog {
    AuditLog {
        at: Some(model.at),
        message: Some(model.message),
    }
}

/// Keeps audit_log rows in memory, for tests and for trying the services without a database. Its copies share the rows.
#[derive(Clone, Default)]
pub struct MemoryAuditLogRepository {
    rows: Arc<Mutex<Vec<AuditLog>>>,
}

impl MemoryAuditLogRepository {
    /// The rows reads see, by primary key.
    fn visible(&self) -> Vec<AuditLog> {
        let mut rows: Vec<AuditLog> = self.rows.lock().unwrap().iter().cloned().collect();
        rows.sort_by(|a, b| key_of(a).partial_cmp(&key_of(b)).unwrap_or(Ordering::Equal));
        rows
    }
}

/// The key of a row, as a tuple of its key values.
fn key_of(row: &AuditLog) -> (Option<chrono::DateTime<chrono::FixedOffset>>, Option<String>) {
    (row.at, row.message.clone())
}

#[async_trait]
impl AuditLogRepository for MemoryAuditLogRepository {
    async fn list(&self, after: Option<(chrono::DateTime<chrono::FixedOffset>, String)>, limit: u64) -> Result<CursorPage<AuditLog, (chrono::DateTime<chrono::FixedOffset>, String)>, DomainError> {
        let after = after.map(|(after0, after1)| (Some(after0), Some(after1)));
        let rows: Vec<_> = self
            .visible()
            .into_iter()
            .filter(|row| after.as_ref().is_none_or(|after| key_of(row).partial_cmp(after) == Some(Ordering::Greater)))
            .collect();
        let more = rows.len() as u64 > limit;
        let items: Vec<AuditLog> = rows.into_iter().take(limit as usize).collect();
        let next = if more { items.last().map(|last| (last.at.expect("at is set"), last.message.clone().expect("message is set"))) } else { None };
        Ok(CursorPage { items, next })
    }
}

