//! The service of the "audit_log" table.

use crate::audit_log::entity::AuditLog;
use crate::common::CursorPage;
use crate::errors::DomainError;
use crate::unit_of_work::UnitOfWork;
use std::sync::Arc;

/// Operations on audit_log. Each write runs in a transaction of its own.
pub struct AuditLogService {
    unit_of_work: Arc<dyn UnitOfWork>,
}

impl AuditLogService {
    pub fn new(unit_of_work: Arc<dyn UnitOfWork>) -> Self {
        Self { unit_of_work }
    }

    /// A page of audit_log after the key after (None for the first page), by primary key.
    pub async fn list_audit_logs(&self, after: Option<(chrono::DateTime<chrono::FixedOffset>, String)>, limit: u64) -> Result<CursorPage<AuditLog, (chrono::DateTime<chrono::FixedOffset>, String)>, DomainError> {
        self.unit_of_work.audit_log().list(after, limit).await
    }
}

