//! The repositories of the "categories" table. Repositories decide nothing.

use async_trait::async_trait;
use crate::categories::table as table;
use crate::categories::entity::Category;
use crate::common::CursorPage;
use crate::database::Db;
use crate::errors::DomainError;
use sea_orm::{ActiveModelTrait, ActiveValue, ColumnTrait, DbErr, EntityTrait, QueryFilter, QueryOrder, QuerySelect};
use std::cmp::Ordering;
use std::sync::{Arc, Mutex};

/// Where categories rows are kept. Services depend only on this trait.
#[async_trait]
pub trait CategoryRepository: Send + Sync {
    /// The row with this primary key, or None.
    async fn find_by_id(&self, id: i64) -> Result<Option<Category>, DomainError>;

    /// At most limit rows after the key after (None for the first page), by primary key, and the key to read the next page from.
    async fn list(&self, after: Option<i64>, limit: u64) -> Result<CursorPage<Category, i64>, DomainError>;

    /// The row with this name, or None.
    async fn find_by_name(&self, name: String) -> Result<Option<Category>, DomainError>;

    /// Stores a new row; the values the database fills are read back.
    async fn insert(&self, entity: Category) -> Result<Category, DomainError>;

    /// Stores the changes made to a row.
    async fn update(&self, entity: Category) -> Result<Category, DomainError>;

    /// Removes a row.
    async fn delete(&self, entity: &Category) -> Result<(), DomainError>;
}

/// Keeps categories rows in the database, through SeaORM: on the connection of the unit of work, or in its transaction.
pub struct SqlCategoryRepository<'a> {
    db: &'a Db,
}

impl<'a> SqlCategoryRepository<'a> {
    pub fn new(db: &'a Db) -> Self {
        Self { db }
    }
}

#[async_trait]
impl CategoryRepository for SqlCategoryRepository<'_> {
    async fn find_by_id(&self, id: i64) -> Result<Option<Category>, DomainError> {
        let db = self.db.executor();
        Ok(table::Entity::find().filter(table::Column::Id.eq(id)).one(&db).await?.map(to_entity))
    }

    async fn list(&self, after: Option<i64>, limit: u64) -> Result<CursorPage<Category, i64>, DomainError> {
        let db = self.db.executor();
        let mut query = table::Entity::find();
        if let Some(after) = after {
            query = query.filter(table::Column::Id.gt(after));
        }
        let rows = query.order_by_asc(table::Column::Id).limit(limit + 1).all(&db).await?;
        let more = rows.len() as u64 > limit;
        let items: Vec<Category> = rows.into_iter().take(limit as usize).map(to_entity).collect();
        let next = if more { items.last().map(|last| last.id.expect("id is set")) } else { None };
        Ok(CursorPage { items, next })
    }

    async fn find_by_name(&self, name: String) -> Result<Option<Category>, DomainError> {
        let db = self.db.executor();
        Ok(table::Entity::find().filter(table::Column::Name.eq(name)).one(&db).await?.map(to_entity))
    }

    async fn insert(&self, entity: Category) -> Result<Category, DomainError> {
        let db = self.db.executor();
        let model = table::ActiveModel {
            name: entity.name.map_or(ActiveValue::NotSet, ActiveValue::Set),
            ..Default::default()
        };
        let stored = table::Entity::insert(model).exec_with_returning(&db).await.map_err(refused)?;
        Ok(to_entity(stored))
    }

    async fn update(&self, entity: Category) -> Result<Category, DomainError> {
        let db = self.db.executor();
        let model = table::ActiveModel {
            id: ActiveValue::Unchanged(entity.id.expect("id is set")),
            name: entity.name.clone().map_or(ActiveValue::NotSet, ActiveValue::Set),
            ..Default::default()
        };
        let stored = model.update(&db).await.map_err(refused)?;
        Ok(to_entity(stored))
    }

    async fn delete(&self, entity: &Category) -> Result<(), DomainError> {
        let db = self.db.executor();
        table::Entity::delete_many().filter(table::Column::Id.eq(entity.id.expect("id is set"))).exec(&db).await.map_err(refused)?;
        Ok(())
    }
}

fn to_entity(model: table::Model) -> Category {
    Category {
        id: Some(model.id),
        name: Some(model.name),
    }
}

/// A refusal of the database (a unique value, a row still pointed to) becomes a Conflict.
fn refused(error: DbErr) -> DomainError {
    if error.sql_err().is_some() {
        DomainError::conflict("Category", &format!("the database refused the change: {error}"), &[])
    } else {
        error.into()
    }
}

/// Keeps categories rows in memory, for tests and for trying the services without a database. Its copies share the rows.
#[derive(Clone, Default)]
pub struct MemoryCategoryRepository {
    rows: Arc<Mutex<Vec<Category>>>,
    next_id: Arc<Mutex<i64>>,
}

impl MemoryCategoryRepository {
    /// The rows reads see, by primary key.
    fn visible(&self) -> Vec<Category> {
        let mut rows: Vec<Category> = self.rows.lock().unwrap().iter().cloned().collect();
        rows.sort_by(|a, b| key_of(a).partial_cmp(&key_of(b)).unwrap_or(Ordering::Equal));
        rows
    }

    /// Keeps a row, in place of the one with its key.
    fn store(&self, entity: &Category) {
        let mut rows = self.rows.lock().unwrap();
        rows.retain(|row| key_of(row) != key_of(entity));
        rows.push(entity.clone());
    }
}

/// The key of a row, as a tuple of its key values.
fn key_of(row: &Category) -> (Option<i64>,) {
    (row.id,)
}

#[async_trait]
impl CategoryRepository for MemoryCategoryRepository {
    async fn find_by_id(&self, id: i64) -> Result<Option<Category>, DomainError> {
        Ok(self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)))
    }

    async fn list(&self, after: Option<i64>, limit: u64) -> Result<CursorPage<Category, i64>, DomainError> {
        let after = after.map(|after| (Some(after),));
        let rows: Vec<_> = self
            .visible()
            .into_iter()
            .filter(|row| after.as_ref().is_none_or(|after| key_of(row).partial_cmp(after) == Some(Ordering::Greater)))
            .collect();
        let more = rows.len() as u64 > limit;
        let items: Vec<Category> = rows.into_iter().take(limit as usize).collect();
        let next = if more { items.last().map(|last| last.id.expect("id is set")) } else { None };
        Ok(CursorPage { items, next })
    }

    async fn find_by_name(&self, name: String) -> Result<Option<Category>, DomainError> {
        Ok(self.visible().into_iter().find(|row| row.name.as_ref() == Some(&name)))
    }

    async fn insert(&self, entity: Category) -> Result<Category, DomainError> {
        let mut entity = entity;
        entity.id = entity.id.or_else(|| {
            let mut next = self.next_id.lock().unwrap();
            *next += 1;
            Some(*next)
        });
        self.store(&entity);
        Ok(entity)
    }

    async fn update(&self, entity: Category) -> Result<Category, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn delete(&self, entity: &Category) -> Result<(), DomainError> {
        self.rows.lock().unwrap().retain(|row| key_of(row) != key_of(entity));
        Ok(())
    }
}

