//! The service of the "categories" table.

use crate::categories::entity::Category;
use crate::common::CursorPage;
use crate::errors::{DomainError, FieldError};
use crate::unit_of_work::UnitOfWork;
use std::sync::Arc;

/// The values of a Category that change: fields left None keep their value; Some(None) empties one.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct CategoryChanges {
    pub name: Option<Option<String>>,
}

/// Operations on categories. Each write runs in a transaction of its own.
pub struct CategoryService {
    unit_of_work: Arc<dyn UnitOfWork>,
}

impl CategoryService {
    pub fn new(unit_of_work: Arc<dyn UnitOfWork>) -> Self {
        Self { unit_of_work }
    }

    /// Stores a new Category after checking it.
    pub async fn create_category(&self, category: Category) -> Result<Category, DomainError> {
        let values = Values { name: category.name.map(Some) };
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        check_values(uow, &values, None).await?;
        let mut entity = Category::default();
        apply_values(&mut entity, &values);
        let created = uow.categories().insert(entity).await?;
        transaction.commit().await?;
        Ok(created)
    }

    /// The Category with this key; NotFound when there is none.
    pub async fn get_category(&self, id: i64) -> Result<Category, DomainError> {
        find(self.unit_of_work.as_ref(), id).await
    }

    /// A page of categories after the key after (None for the first page), by primary key.
    pub async fn list_categories(&self, after: Option<i64>, limit: u64) -> Result<CursorPage<Category, i64>, DomainError> {
        self.unit_of_work.categories().list(after, limit).await
    }

    /// Changes the given values of a Category.
    pub async fn update_category(&self, id: i64, changes: CategoryChanges) -> Result<Category, DomainError> {
        let values = given(changes);
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let mut current = find(uow, id).await?;
        check_values(uow, &values, Some(&current)).await?;
        apply_values(&mut current, &values);
        let updated = uow.categories().update(current).await?;
        transaction.commit().await?;
        Ok(updated)
    }

    /// Deletes a Category.
    pub async fn delete_category(&self, id: i64) -> Result<(), DomainError> {
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let current = find(uow, id).await?;
        for row in uow.products().list_by_category_id(current.id.expect("id is set")).await? {
            uow.products().delete(&row).await?;
        }
        uow.categories().delete(&current).await?;
        transaction.commit().await?;
        Ok(())
    }

    /// The Category with this name, or None.
    pub async fn find_category_by_name(&self, name: String) -> Result<Option<Category>, DomainError> {
        self.unit_of_work.categories().find_by_name(name).await
    }
}

/// The values a create or an update gives, by field: None when not given, Some(None) when given empty.
#[derive(Default)]
struct Values {
    name: Option<Option<String>>,
}

/// Checks the values against the rules of the "categories" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(_uow: &dyn UnitOfWork, values: &Values, current: Option<&Category>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.name.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.name.is_some() {
                errors.push(FieldError::new("name", "is required"));
            }
        }
        Some(value) => {
            if value.chars().count() > 60 {
                errors.push(FieldError::new("name", "is longer than 60 characters"));
            }
        }
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "Category".to_string(), errors })
    }
}

/// Values that must be unique are not taken by another row.
async fn check_unique(uow: &dyn UnitOfWork, values: &Values, current: Option<&Category>) -> Result<(), DomainError> {
    {
        let name = values.name.clone().unwrap_or_else(|| current.and_then(|current| current.name.clone()));
        if let Some(name) = name {
            if let Some(other) = uow.categories().find_by_name(name).await? {
                if current.is_none_or(|current| other.id != current.id) {
                    return Err(DomainError::conflict("Category", "name is already taken", &["name"]));
                }
            }
        }
    }
    Ok(())
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&Category>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    check_unique(uow, values, current).await
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut Category, values: &Values) {
    if let Some(value) = &values.name {
        entity.name = value.clone();
    }
}

/// The values an update gives, by field.
fn given(changes: CategoryChanges) -> Values {
    Values { name: changes.name }
}

/// The Category with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, id: i64) -> Result<Category, DomainError> {
    uow.categories().find_by_id(id).await?.ok_or_else(|| DomainError::not_found("Category", id))
}

