    }

    /// Changes the given values of a Customer.
    pub async fn update_customer(&self, id: i64, changes: CustomerChanges) -> Result<Customer, DomainError> {
        let values = given(changes);
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let mut current = find(uow, id).await?;
        check_values(uow, &values, Some(&current)).await?;
        apply_values(&mut current, &values);
        let updated = uow.customers().update(current).await?;
        transaction.commit().await?;
        Ok(updated)
    }

    /// Deletes a Customer.
    pub async fn delete_customer(&self, id: i64) -> Result<(), DomainError> {
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let current = find(uow, id).await?;
        for row in uow.orders().list_by_customer_id(current.id.expect("id is set")).await? {
            uow.orders().delete(&row).await?;
        }
        uow.customers().delete(&current).await?;
        transaction.commit().await?;
        Ok(())
    }

    /// The Customer with this email, or None.
    pub async fn find_customer_by_email(&self, email: String) -> Result<Option<Customer>, DomainError> {
        self.unit_of_work.customers().find_by_email(email).await
    }
}

/// The values a create or an update gives, by field: None when not given, Some(None) when given empty.
#[derive(Default)]
struct Values {
    email: Option<Option<String>>,
    password_hash: Option<Option<String>>,
}

/// Checks the values against the rules of the "customers" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(_uow: &dyn UnitOfWork, values: &Values, current: Option<&Customer>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.email.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.email.is_some() {
                errors.push(FieldError::new("email", "is required"));
            }
        }
        Some(value) => {
            if value.chars().count() > 120 {
                errors.push(FieldError::new("email", "is longer than 120 characters"));
            }
        }
    }
    match values.password_hash.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.password_hash.is_some() {
                errors.push(FieldError::new("password_hash", "is required"));
            }
        }
        Some(_) => {}
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "Customer".to_string(), errors })
    }
}

/// Values that must be unique are not taken by another row.
async fn check_unique(uow: &dyn UnitOfWork, values: &Values, current: Option<&Customer>) -> Result<(), DomainError> {
    {
        let email = values.email.clone().unwrap_or_else(|| current.and_then(|current| current.email.clone()));
        if let Some(email) = email {
            if let Some(other) = uow.customers().find_by_email(email).await? {
                if current.is_none_or(|current| other.id != current.id) {
                    return Err(DomainError::conflict("Customer", "email is already taken", &["email"]));
                }
            }
        }
    }
    Ok(())
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&Customer>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    check_unique(uow, values, current).await
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut Customer, values: &Values) {
    if let Some(value) = &values.email {
        entity.email = value.clone();
    }
    if let Some(value) = &values.password_hash {
        entity.password_hash = value.clone();
    }
}

/// The values an update gives, by field.
fn given(changes: CustomerChanges) -> Values {
    Values { email: changes.email, password_hash: changes.password_hash }
}

/// The Customer with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, id: i64) -> Result<Customer, DomainError> {
    uow.customers().find_by_id(id).await?.ok_or_else(|| DomainError::not_found("Customer", id))
}

