//! The repositories of the "order_lines" table. Repositories decide nothing.

use async_trait::async_trait;
use crate::common::CursorPage;
use crate::database::Db;
use crate::errors::DomainError;
use crate::order_lines::table as table;
use crate::order_lines::entity::OrderLine;
use sea_orm::{ActiveModelTrait, ActiveValue, ColumnTrait, Condition, DbErr, EntityTrait, QueryFilter, QueryOrder, QuerySelect};
use std::cmp::Ordering;
use std::sync::{Arc, Mutex};

/// Where order_lines rows are kept. Services depend only on this trait.
#[async_trait]
pub trait OrderLineRepository: Send + Sync {
    /// The row with this primary key, or None.
    async fn find_by_order_id_and_line(&self, order_id: i64, line: i32) -> Result<Option<OrderLine>, DomainError>;

    /// At most limit rows after the key after (None for the first page), by primary key, and the key to read the next page from.
    async fn list(&self, after: Option<(i64, i32)>, limit: u64) -> Result<CursorPage<OrderLine, (i64, i32)>, DomainError>;

    /// Rows with this order_id, by primary key.
    async fn list_by_order_id(&self, order_id: i64) -> Result<Vec<OrderLine>, DomainError>;

    /// Rows with this product_id, by primary key.
    async fn list_by_product_id(&self, product_id: i64) -> Result<Vec<OrderLine>, DomainError>;

    /// Stores a new row; the values the database fills are read back.
    async fn insert(&self, entity: OrderLine) -> Result<OrderLine, DomainError>;

    /// Stores the changes made to a row.
    async fn update(&self, entity: OrderLine) -> Result<OrderLine, DomainError>;

    /// Removes a row.
    async fn delete(&self, entity: &OrderLine) -> Result<(), DomainError>;
}

/// Keeps order_lines rows in the database, through SeaORM: on the connection of the unit of work, or in its transaction.
pub struct SqlOrderLineRepository<'a> {
    db: &'a Db,
}

impl<'a> SqlOrderLineRepository<'a> {
    pub fn new(db: &'a Db) -> Self {
        Self { db }
    }
}

#[async_trait]
impl OrderLineRepository for SqlOrderLineRepository<'_> {
    async fn find_by_order_id_and_line(&self, order_id: i64, line: i32) -> Result<Option<OrderLine>, DomainError> {
        let db = self.db.executor();
        Ok(table::Entity::find().filter(table::Column::OrderId.eq(order_id)).filter(table::Column::Line.eq(line)).one(&db).await?.map(to_entity))
    }

    async fn list(&self, after: Option<(i64, i32)>, limit: u64) -> Result<CursorPage<OrderLine, (i64, i32)>, DomainError> {
        let db = self.db.executor();
        let mut query = table::Entity::find();
        if let Some(after) = after {
            let (after0, after1) = after;
            query = query.filter(Condition::any().add(table::Column::OrderId.gt(after0.clone())).add(Condition::all().add(table::Column::OrderId.eq(after0.clone())).add(table::Column::Line.gt(after1.clone()))));
        }
        let rows = query.order_by_asc(table::Column::OrderId).order_by_asc(table::Column::Line).limit(limit + 1).all(&db).await?;
        let more = rows.len() as u64 > limit;
        let items: Vec<OrderLine> = rows.into_iter().take(limit as usize).map(to_entity).collect();
        let next = if more { items.last().map(|last| (last.order_id.expect("order_id is set"), last.line.expect("line is set"))) } else { None };
        Ok(CursorPage { items, next })
    }

    async fn list_by_order_id(&self, order_id: i64) -> Result<Vec<OrderLine>, DomainError> {
        let db = self.db.executor();
        Ok(table::Entity::find().filter(table::Column::OrderId.eq(order_id)).order_by_asc(table::Column::OrderId).order_by_asc(table::Column::Line).all(&db).await?.into_iter().map(to_entity).collect())
    }

    async fn list_by_product_id(&self, product_id: i64) -> Result<Vec<OrderLine>, DomainError> {
        let db = self.db.executor();
        Ok(table::Entity::find().filter(table::Column::ProductId.eq(product_id)).order_by_asc(table::Column::OrderId).order_by_asc(table::Column::Line).all(&db).await?.into_iter().map(to_entity).collect())
    }

    async fn insert(&self, entity: OrderLine) -> Result<OrderLine, DomainError> {
        let db = self.db.executor();
        let model = table::ActiveModel {
            order_id: entity.order_id.map_or(ActiveValue::NotSet, ActiveValue::Set),
            line: entity.line.map_or(ActiveValue::NotSet, ActiveValue::Set),
            product_id: entity.product_id.map_or(ActiveValue::NotSet, ActiveValue::Set),
            quantity: entity.quantity.map_or(ActiveValue::NotSet, ActiveValue::Set),
            ..Default::default()
        };
        let stored = table::Entity::insert(model).exec_with_returning(&db).await.map_err(refused)?;
        Ok(to_entity(stored))
    }

    async fn update(&self, entity: OrderLine) -> Result<OrderLine, DomainError> {
        let db = self.db.executor();
        let model = table::ActiveModel {
            order_id: ActiveValue::Unchanged(entity.order_id.expect("order_id is set")),
            line: ActiveValue::Unchanged(entity.line.expect("line is set")),
            product_id: entity.product_id.map_or(ActiveValue::NotSet, ActiveValue::Set),
            quantity: entity.quantity.map_or(ActiveValue::NotSet, ActiveValue::Set),
            ..Default::default()
        };
        let stored = model.update(&db).await.map_err(refused)?;
        Ok(to_entity(stored))
    }

    async fn delete(&self, entity: &OrderLine) -> Result<(), DomainError> {
        let db = self.db.executor();
        table::Entity::delete_many().filter(table::Column::OrderId.eq(entity.order_id.expect("order_id is set"))).filter(table::Column::Line.eq(entity.line.expect("line is set"))).exec(&db).await.map_err(refused)?;
        Ok(())
    }
}

fn to_entity(model: table::Model) -> OrderLine {
    OrderLine {
        order_id: Some(model.order_id),
        line: Some(model.line),
        product_id: Some(model.product_id),
        quantity: Some(model.quantity),
    }
}

/// A refusal of the database (a unique value, a row still pointed to) becomes a Conflict.
fn refused(error: DbErr) -> DomainError {
    if error.sql_err().is_some() {
        DomainError::conflict("OrderLine", &format!("the database refused the change: {error}"), &[])
    } else {
        error.into()
    }
}

/// Keeps order_lines rows in memory, for tests and for trying the services without a database. Its copies share the rows.
#[derive(Clone, Default)]
pub struct MemoryOrderLineRepository {
    rows: Arc<Mutex<Vec<OrderLine>>>,
}

impl MemoryOrderLineRepository {
    /// The rows reads see, by primary key.
    fn visible(&self) -> Vec<OrderLine> {
        let mut rows: Vec<OrderLine> = self.rows.lock().unwrap().iter().cloned().collect();
        rows.sort_by(|a, b| key_of(a).partial_cmp(&key_of(b)).unwrap_or(Ordering::Equal));
        rows
    }

    /// Keeps a row, in place of the one with its key.
    fn store(&self, entity: &OrderLine) {
        let mut rows = self.rows.lock().unwrap();
        rows.retain(|row| key_of(row) != key_of(entity));
        rows.push(entity.clone());
    }
}

/// The key of a row, as a tuple of its key values.
fn key_of(row: &OrderLine) -> (Option<i64>, Option<i32>) {
    (row.order_id, row.line)
}

#[async_trait]
impl OrderLineRepository for MemoryOrderLineRepository {
    async fn find_by_order_id_and_line(&self, order_id: i64, line: i32) -> Result<Option<OrderLine>, DomainError> {
        Ok(self.visible().into_iter().find(|row| row.order_id.as_ref() == Some(&order_id) && row.line.as_ref() == Some(&line)))
    }

    async fn list(&self, after: Option<(i64, i32)>, limit: u64) -> Result<CursorPage<OrderLine, (i64, i32)>, DomainError> {
        let after = after.map(|(after0, after1)| (Some(after0), Some(after1)));
        let rows: Vec<_> = self
            .visible()
            .into_iter()
            .filter(|row| after.as_ref().is_none_or(|after| key_of(row).partial_cmp(after) == Some(Ordering::Greater)))
            .collect();
        let more = rows.len() as u64 > limit;
        let items: Vec<OrderLine> = rows.into_iter().take(limit as usize).collect();
        let next = if more { items.last().map(|last| (last.order_id.expect("order_id is set"), last.line.expect("line is set"))) } else { None };
        Ok(CursorPage { items, next })
    }

    async fn list_by_order_id(&self, order_id: i64) -> Result<Vec<OrderLine>, DomainError> {
        Ok(self.visible().into_iter().filter(|row| row.order_id.as_ref() == Some(&order_id)).collect())
    }

    async fn list_by_product_id(&self, product_id: i64) -> Result<Vec<OrderLine>, DomainError> {
        Ok(self.visible().into_iter().filter(|row| row.product_id.as_ref() == Some(&product_id)).collect())
    }

    async fn insert(&self, entity: OrderLine) -> Result<OrderLine, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn update(&self, entity: OrderLine) -> Result<OrderLine, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn delete(&self, entity: &OrderLine) -> Result<(), DomainError> {
        self.rows.lock().unwrap().retain(|row| key_of(row) != key_of(entity));
        Ok(())
    }
}

