/// The values of a OrderLine that change: fields left None keep their value; Some(None) empties one.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct OrderLineChanges {
    pub product_id: Option<Option<i64>>,
    pub quantity: Option<Option<i32>>,
}

/// Operations on order_lines. Each write runs in a transaction of its own.
pub struct OrderLineService {
    unit_of_work: Arc<dyn UnitOfWork>,
}

impl OrderLineService {
    pub fn new(unit_of_work: Arc<dyn UnitOfWork>) -> Self {
        Self { unit_of_work }
    }

    /// Stores a new OrderLine after checking it.
    pub async fn create_order_line(&self, order_line: OrderLine) -> Result<OrderLine, DomainError> {
        let values = Values { order_id: order_line.order_id.map(Some), line: order_line.line.map(Some), product_id: order_line.product_id.map(Some), quantity: order_line.quantity.map(Some) };
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        check_values(uow, &values, None).await?;
        let mut entity = OrderLine::default();
        apply_values(&mut entity, &values);
        let created = uow.order_lines().insert(entity).await?;
        transaction.commit().await?;
        Ok(created)
    }

    /// The OrderLine with this key; NotFound when there is none.
    pub async fn get_order_line(&self, order_id: i64, line: i32) -> Result<OrderLine, DomainError> {
        find(self.unit_of_work.as_ref(), order_id, line).await
    }

    /// A page of order_lines after the key after (None for the first page), by primary key.
    pub async fn list_order_lines(&self, after: Option<(i64, i32)>, limit: u64) -> Result<CursorPage<OrderLine, (i64, i32)>, DomainError> {
        self.unit_of_work.order_lines().list(after, limit).await
    }

    /// Changes the given values of a OrderLine.
    pub async fn update_order_line(&self, order_id: i64, line: i32, changes: OrderLineChanges) -> Result<OrderLine, DomainError> {
        let values = given(changes);
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let mut current = find(uow, order_id, line).await?;
        check_values(uow, &values, Some(&current)).await?;
        apply_values(&mut current, &values);
        let updated = uow.order_lines().update(current).await?;
        transaction.commit().await?;
        Ok(updated)
    }

    /// Deletes a OrderLine.
    pub async fn delete_order_line(&self, order_id: i64, line: i32) -> Result<(), DomainError> {
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let current = find(uow, order_id, line).await?;
        uow.order_lines().delete(&current).await?;
        transaction.commit().await?;
        Ok(())
    }

    /// The order_lines with this order_id.
    pub async fn list_order_lines_by_order_id(&self, order_id: i64) -> Result<Vec<OrderLine>, DomainError> {
        self.unit_of_work.order_lines().list_by_order_id(order_id).await
    }

    /// The order_lines with this product_id.
    pub async fn list_order_lines_by_product_id(&self, product_id: i64) -> Result<Vec<OrderLine>, DomainError> {
        self.unit_of_work.order_lines().list_by_product_id(product_id).await
    }
}

/// The values a create or an update gives, by field: None when not given, Some(None) when given empty.
#[derive(Default)]
struct Values {
    order_id: Option<Option<i64>>,
    line: Option<Option<i32>>,
    product_id: Option<Option<i64>>,
    quantity: Option<Option<i32>>,
}

/// Checks the values against the rules of the "order_lines" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(uow: &dyn UnitOfWork, values: &Values, current: Option<&OrderLine>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.order_id.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.order_id.is_some() {
                errors.push(FieldError::new("order_id", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.line.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.line.is_some() {
                errors.push(FieldError::new("line", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.product_id.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.product_id.is_some() {
                errors.push(FieldError::new("product_id", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.quantity.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.quantity.is_some() {
                errors.push(FieldError::new("quantity", "is required"));
            }
        }
        Some(_) => {}
    }
    {
        let order_id = values.order_id.clone().unwrap_or_else(|| current.and_then(|current| current.order_id));
        if let Some(order_id) = order_id {
            if uow.orders().find_by_id(order_id).await?.is_none() {
                errors.push(FieldError::new("order_id", "no Order has this key"));
            }
        }
    }
    {
        let product_id = values.product_id.clone().unwrap_or_else(|| current.and_then(|current| current.product_id));
        if let Some(product_id) = product_id {
            if uow.products().find_by_id(product_id).await?.is_none() {
                errors.push(FieldError::new("product_id", "no Product has this key"));
            }
        }
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "OrderLine".to_string(), errors })
    }
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&OrderLine>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
