//! The repositories of the "orders" table. Repositories decide nothing.

use async_trait::async_trait;
use crate::common::CursorPage;
use crate::database::Db;
use crate::errors::DomainError;
use crate::orders::table as table;
use crate::orders::entity::Order;
use sea_orm::{ActiveModelTrait, ActiveValue, ColumnTrait, DbErr, EntityTrait, QueryFilter, QueryOrder, QuerySelect};
use std::cmp::Ordering;
use std::sync::{Arc, Mutex};

/// Where orders rows are kept. Services depend only on this trait.
#[async_trait]
pub trait OrderRepository: Send + Sync {
    /// The row with this primary key, or None.
    async fn find_by_id(&self, id: i64) -> Result<Option<Order>, DomainError>;

    /// At most limit rows after the key after (None for the first page), by primary key, and the key to read the next page from.
    async fn list(&self, after: Option<i64>, limit: u64) -> Result<CursorPage<Order, i64>, DomainError>;

    /// Rows with this customer_id, by primary key.
    async fn list_by_customer_id(&self, customer_id: i64) -> Result<Vec<Order>, DomainError>;

    /// Stores a new row; the values the database fills are read back.
    async fn insert(&self, entity: Order) -> Result<Order, DomainError>;

    /// Stores the changes made to a row.
    async fn update(&self, entity: Order) -> Result<Order, DomainError>;

    /// Removes a row.
    async fn delete(&self, entity: &Order) -> Result<(), DomainError>;
}

/// Keeps orders rows in the database, through SeaORM: on the connection of the unit of work, or in its transaction.
pub struct SqlOrderRepository<'a> {
    db: &'a Db,
}

impl<'a> SqlOrderRepository<'a> {
    pub fn new(db: &'a Db) -> Self {
        Self { db }
    }
}

#[async_trait]
impl OrderRepository for SqlOrderRepository<'_> {
    async fn find_by_id(&self, id: i64) -> Result<Option<Order>, DomainError> {
        let db = self.db.executor();
        Ok(table::Entity::find().filter(table::Column::Id.eq(id)).one(&db).await?.map(to_entity))
    }

    async fn list(&self, after: Option<i64>, limit: u64) -> Result<CursorPage<Order, i64>, DomainError> {
        let db = self.db.executor();
        let mut query = table::Entity::find();
        if let Some(after) = after {
            query = query.filter(table::Column::Id.gt(after));
        }
        let rows = query.order_by_asc(table::Column::Id).limit(limit + 1).all(&db).await?;
        let more = rows.len() as u64 > limit;
        let items: Vec<Order> = rows.into_iter().take(limit as usize).map(to_entity).collect();
        let next = if more { items.last().map(|last| last.id.expect("id is set")) } else { None };
        Ok(CursorPage { items, next })
    }

    async fn list_by_customer_id(&self, customer_id: i64) -> Result<Vec<Order>, DomainError> {
        let db = self.db.executor();
        Ok(table::Entity::find().filter(table::Column::CustomerId.eq(customer_id)).order_by_asc(table::Column::Id).all(&db).await?.into_iter().map(to_entity).collect())
    }

    async fn insert(&self, entity: Order) -> Result<Order, DomainError> {
        let db = self.db.executor();
        let model = table::ActiveModel {
            customer_id: entity.customer_id.map_or(ActiveValue::NotSet, ActiveValue::Set),
            ..Default::default()
        };
        let stored = table::Entity::insert(model).exec_with_returning(&db).await.map_err(refused)?;
        Ok(to_entity(stored))
    }

    async fn update(&self, entity: Order) -> Result<Order, DomainError> {
        let db = self.db.executor();
        let model = table::ActiveModel {
            id: ActiveValue::Unchanged(entity.id.expect("id is set")),
            customer_id: entity.customer_id.map_or(ActiveValue::NotSet, ActiveValue::Set),
            ..Default::default()
        };
        let stored = model.update(&db).await.map_err(refused)?;
        Ok(to_entity(stored))
    }

    async fn delete(&self, entity: &Order) -> Result<(), DomainError> {
        let db = self.db.executor();
        table::Entity::delete_many().filter(table::Column::Id.eq(entity.id.expect("id is set"))).exec(&db).await.map_err(refused)?;
        Ok(())
    }
}

fn to_entity(model: table::Model) -> Order {
    Order {
        id: Some(model.id),
        customer_id: Some(model.customer_id),
        placed_at: Some(model.placed_at),
    }
}

/// A refusal of the database (a unique value, a row still pointed to) becomes a Conflict.
fn refused(error: DbErr) -> DomainError {
    if error.sql_err().is_some() {
        DomainError::conflict("Order", &format!("the database refused the change: {error}"), &[])
    } else {
        error.into()
    }
}

/// Keeps orders rows in memory, for tests and for trying the services without a database. Its copies share the rows.
#[derive(Clone, Default)]
pub struct MemoryOrderRepository {
    rows: Arc<Mutex<Vec<Order>>>,
    next_id: Arc<Mutex<i64>>,
}

impl MemoryOrderRepository {
    /// The rows reads see, by primary key.
    fn visible(&self) -> Vec<Order> {
        let mut rows: Vec<Order> = self.rows.lock().unwrap().iter().cloned().collect();
        rows.sort_by(|a, b| key_of(a).partial_cmp(&key_of(b)).unwrap_or(Ordering::Equal));
        rows
    }

    /// Keeps a row, in place of the one with its key.
    fn store(&self, entity: &Order) {
        let mut rows = self.rows.lock().unwrap();
        rows.retain(|row| key_of(row) != key_of(entity));
        rows.push(entity.clone());
    }
}

/// The key of a row, as a tuple of its key values.
fn key_of(row: &Order) -> (Option<i64>,) {
    (row.id,)
}

#[async_trait]
impl OrderRepository for MemoryOrderRepository {
    async fn find_by_id(&self, id: i64) -> Result<Option<Order>, DomainError> {
        Ok(self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)))
    }

    async fn list(&self, after: Option<i64>, limit: u64) -> Result<CursorPage<Order, i64>, DomainError> {
        let after = after.map(|after| (Some(after),));
        let rows: Vec<_> = self
            .visible()
            .into_iter()
            .filter(|row| after.as_ref().is_none_or(|after| key_of(row).partial_cmp(after) == Some(Ordering::Greater)))
            .collect();
        let more = rows.len() as u64 > limit;
        let items: Vec<Order> = rows.into_iter().take(limit as usize).collect();
        let next = if more { items.last().map(|last| last.id.expect("id is set")) } else { None };
        Ok(CursorPage { items, next })
    }

    async fn list_by_customer_id(&self, customer_id: i64) -> Result<Vec<Order>, DomainError> {
        Ok(self.visible().into_iter().filter(|row| row.customer_id.as_ref() == Some(&customer_id)).collect())
    }

    async fn insert(&self, entity: Order) -> Result<Order, DomainError> {
        let mut entity = entity;
        entity.id = entity.id.or_else(|| {
            let mut next = self.next_id.lock().unwrap();
            *next += 1;
            Some(*next)
        });
        entity.placed_at = entity.placed_at.or_else(|| Some(chrono::Utc::now().fixed_offset()));
        self.store(&entity);
        Ok(entity)
    }

    async fn update(&self, entity: Order) -> Result<Order, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn delete(&self, entity: &Order) -> Result<(), DomainError> {
        self.rows.lock().unwrap().retain(|row| key_of(row) != key_of(entity));
        Ok(())
    }
}

