//! The service of the "orders" table.

use crate::common::CursorPage;
use crate::errors::{DomainError, FieldError};
use crate::orders::entity::Order;
use crate::unit_of_work::UnitOfWork;
use std::sync::Arc;

/// The values of a Order that change: fields left None keep their value; Some(None) empties one.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct OrderChanges {
    pub customer_id: Option<Option<i64>>,
}

/// Operations on orders. Each write runs in a transaction of its own.
pub struct OrderService {
    unit_of_work: Arc<dyn UnitOfWork>,
}

impl OrderService {
    pub fn new(unit_of_work: Arc<dyn UnitOfWork>) -> Self {
        Self { unit_of_work }
    }

    /// Stores a new Order after checking it.
    pub async fn create_order(&self, order: Order) -> Result<Order, DomainError> {
        let values = Values { customer_id: order.customer_id.map(Some) };
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        check_values(uow, &values, None).await?;
        let mut entity = Order::default();
        apply_values(&mut entity, &values);
        let created = uow.orders().insert(entity).await?;
        transaction.commit().await?;
        Ok(created)
    }

    /// The Order with this key; NotFound when there is none.
    pub async fn get_order(&self, id: i64) -> Result<Order, DomainError> {
        find(self.unit_of_work.as_ref(), id).await
    }

    /// A page of orders after the key after (None for the first page), by primary key.
    pub async fn list_orders(&self, after: Option<i64>, limit: u64) -> Result<CursorPage<Order, i64>, DomainError> {
        self.unit_of_work.orders().list(after, limit).await
    }

    /// Changes the given values of a Order.
    pub async fn update_order(&self, id: i64, changes: OrderChanges) -> Result<Order, DomainError> {
        let values = given(changes);
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let mut current = find(uow, id).await?;
        check_values(uow, &values, Some(&current)).await?;
        apply_values(&mut current, &values);
        let updated = uow.orders().update(current).await?;
        transaction.commit().await?;
        Ok(updated)
    }

    /// Deletes a Order.
    pub async fn delete_order(&self, id: i64) -> Result<(), DomainError> {
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let current = find(uow, id).await?;
        uow.orders().delete(&current).await?;
        transaction.commit().await?;
        Ok(())
    }

    /// The orders with this customer_id.
    pub async fn list_orders_by_customer_id(&self, customer_id: i64) -> Result<Vec<Order>, DomainError> {
        self.unit_of_work.orders().list_by_customer_id(customer_id).await
    }
}

/// The values a create or an update gives, by field: None when not given, Some(None) when given empty.
#[derive(Default)]
struct Values {
    customer_id: Option<Option<i64>>,
}

/// Checks the values against the rules of the "orders" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(uow: &dyn UnitOfWork, values: &Values, current: Option<&Order>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.customer_id.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.customer_id.is_some() {
                errors.push(FieldError::new("customer_id", "is required"));
            }
        }
        Some(_) => {}
    }
    {
        let customer_id = values.customer_id.clone().unwrap_or_else(|| current.and_then(|current| current.customer_id));
        if let Some(customer_id) = customer_id {
            if uow.customers().find_by_id(customer_id).await?.is_none() {
                errors.push(FieldError::new("customer_id", "no Customer has this key"));
            }
        }
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "Order".to_string(), errors })
    }
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&Order>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    Ok(())
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut Order, values: &Values) {
    if let Some(value) = &values.customer_id {
        entity.customer_id = *value;
    }
}

/// The values an update gives, by field.
fn given(changes: OrderChanges) -> Values {
    Values { customer_id: changes.customer_id }
}

/// The Order with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, id: i64) -> Result<Order, DomainError> {
    uow.orders().find_by_id(id).await?.ok_or_else(|| DomainError::not_found("Order", id))
}

