    tag_id: Option<Option<i64>>,
}

/// Checks the values against the rules of the "product_tags" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(uow: &dyn UnitOfWork, values: &Values, current: Option<&ProductTag>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.product_id.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.product_id.is_some() {
                errors.push(FieldError::new("product_id", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.tag_id.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.tag_id.is_some() {
                errors.push(FieldError::new("tag_id", "is required"));
            }
        }
        Some(_) => {}
    }
    {
        let product_id = values.product_id.clone().unwrap_or_else(|| current.and_then(|current| current.product_id));
        if let Some(product_id) = product_id {
            if uow.products().find_by_id(product_id).await?.is_none() {
                errors.push(FieldError::new("product_id", "no Product has this key"));
            }
        }
    }
    {
        let tag_id = values.tag_id.clone().unwrap_or_else(|| current.and_then(|current| current.tag_id));
        if let Some(tag_id) = tag_id {
            if uow.tags().find_by_id(tag_id).await?.is_none() {
                errors.push(FieldError::new("tag_id", "no Tag has this key"));
            }
        }
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "ProductTag".to_string(), errors })
    }
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&ProductTag>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    Ok(())
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut ProductTag, values: &Values) {
    if let Some(value) = &values.product_id {
        entity.product_id = *value;
    }
    if let Some(value) = &values.tag_id {
        entity.tag_id = *value;
    }
}

/// The values an update gives, by field.
fn given(_changes: ProductTagChanges) -> Values {
    Values::default()
}

/// The ProductTag with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, product_id: i64, tag_id: i64) -> Result<ProductTag, DomainError> {
    uow.product_tags().find_by_product_id_and_tag_id(product_id, tag_id).await?.ok_or_else(|| DomainError::not_found("ProductTag", (product_id, tag_id)))
}

