//! The repositories of the "products" table. Repositories decide nothing.

use async_trait::async_trait;
use crate::common::CursorPage;
use crate::database::Db;
use crate::errors::DomainError;
use crate::products::table as table;
use crate::products::entity::Product;
use sea_orm::{ActiveModelTrait, ActiveValue, ColumnTrait, DbErr, EntityTrait, QueryFilter, QueryOrder, QuerySelect};
use std::cmp::Ordering;
use std::sync::{Arc, Mutex};

/// Where products rows are kept. Services depend only on this trait.
#[async_trait]
pub trait ProductRepository: Send + Sync {
    /// The row with this primary key, or None.
    async fn find_by_id(&self, id: i64) -> Result<Option<Product>, DomainError>;

    /// At most limit rows after the key after (None for the first page), by primary key, and the key to read the next page from.
    async fn list(&self, after: Option<i64>, limit: u64) -> Result<CursorPage<Product, i64>, DomainError>;

    /// Rows with this category_id, by primary key.
    async fn list_by_category_id(&self, category_id: i64) -> Result<Vec<Product>, DomainError>;

    /// Rows with this status, by primary key.
    async fn find_all_by_status(&self, status: String) -> Result<Vec<Product>, DomainError>;

    /// Stores a new row; the values the database fills are read back.
    async fn insert(&self, entity: Product) -> Result<Product, DomainError>;

    /// Stores the changes made to a row.
    async fn update(&self, entity: Product) -> Result<Product, DomainError>;

    /// Removes a row.
    async fn delete(&self, entity: &Product) -> Result<(), DomainError>;
}

/// Keeps products rows in the database, through SeaORM: on the connection of the unit of work, or in its transaction.
pub struct SqlProductRepository<'a> {
    db: &'a Db,
}

impl<'a> SqlProductRepository<'a> {
    pub fn new(db: &'a Db) -> Self {
        Self { db }
    }
}

#[async_trait]
impl ProductRepository for SqlProductRepository<'_> {
    async fn find_by_id(&self, id: i64) -> Result<Option<Product>, DomainError> {
        let db = self.db.executor();
        Ok(table::Entity::find().filter(table::Column::Id.eq(id)).one(&db).await?.map(to_entity))
    }

    async fn list(&self, after: Option<i64>, limit: u64) -> Result<CursorPage<Product, i64>, DomainError> {
        let db = self.db.executor();
        let mut query = table::Entity::find();
        if let Some(after) = after {
            query = query.filter(table::Column::Id.gt(after));
        }
        let rows = query.order_by_asc(table::Column::Id).limit(limit + 1).all(&db).await?;
        let more = rows.len() as u64 > limit;
        let items: Vec<Product> = rows.into_iter().take(limit as usize).map(to_entity).collect();
        let next = if more { items.last().map(|last| last.id.expect("id is set")) } else { None };
        Ok(CursorPage { items, next })
    }

    async fn list_by_category_id(&self, category_id: i64) -> Result<Vec<Product>, DomainError> {
        let db = self.db.executor();
        Ok(table::Entity::find().filter(table::Column::CategoryId.eq(category_id)).order_by_asc(table::Column::Id).all(&db).await?.into_iter().map(to_entity).collect())
    }

    async fn find_all_by_status(&self, status: String) -> Result<Vec<Product>, DomainError> {
        let db = self.db.executor();
        Ok(table::Entity::find().filter(table::Column::Status.eq(status)).order_by_asc(table::Column::Id).all(&db).await?.into_iter().map(to_entity).collect())
    }

    async fn insert(&self, entity: Product) -> Result<Product, DomainError> {
        let db = self.db.executor();
        let model = table::ActiveModel {
            category_id: entity.category_id.map_or(ActiveValue::NotSet, ActiveValue::Set),
            name: entity.name.map_or(ActiveValue::NotSet, ActiveValue::Set),
            price: entity.price.map_or(ActiveValue::NotSet, ActiveValue::Set),
            status: entity.status.map_or(ActiveValue::NotSet, ActiveValue::Set),
            version: entity.version.map_or(ActiveValue::NotSet, ActiveValue::Set),
            deleted_at: entity.deleted_at.map_or(ActiveValue::NotSet, |value| ActiveValue::Set(Some(value))),
            ..Default::default()
        };
        let stored = table::Entity::insert(model).exec_with_returning(&db).await.map_err(refused)?;
        Ok(to_entity(stored))
    }

    async fn update(&self, entity: Product) -> Result<Product, DomainError> {
        let db = self.db.executor();
        let model = table::ActiveModel {
            id: ActiveValue::Unchanged(entity.id.expect("id is set")),
            category_id: entity.category_id.map_or(ActiveValue::NotSet, ActiveValue::Set),
            name: entity.name.clone().map_or(ActiveValue::NotSet, ActiveValue::Set),
            price: entity.price.map_or(ActiveValue::NotSet, ActiveValue::Set),
            status: entity.status.clone().map_or(ActiveValue::NotSet, ActiveValue::Set),
            version: entity.version.map_or(ActiveValue::NotSet, ActiveValue::Set),
            deleted_at: ActiveValue::Set(entity.deleted_at),
            ..Default::default()
        };
        let stored = model.update(&db).await.map_err(refused)?;
        Ok(to_entity(stored))
    }

    async fn delete(&self, entity: &Product) -> Result<(), DomainError> {
        let db = self.db.executor();
        table::Entity::delete_many().filter(table::Column::Id.eq(entity.id.expect("id is set"))).exec(&db).await.map_err(refused)?;
        Ok(())
    }
}

fn to_entity(model: table::Model) -> Product {
    Product {
        id: Some(model.id),
        category_id: Some(model.category_id),
        name: Some(model.name),
        price: Some(model.price),
        status: Some(model.status),
        version: Some(model.version),
        deleted_at: model.deleted_at,
    }
}

/// A refusal of the database (a unique value, a row still pointed to) becomes a Conflict.
fn refused(error: DbErr) -> DomainError {
    if error.sql_err().is_some() {
        DomainError::conflict("Product", &format!("the database refused the change: {error}"), &[])
    } else {
        error.into()
    }
}

/// Keeps products rows in memory, for tests and for trying the services without a database. Its copies share the rows.
#[derive(Clone, Default)]
pub struct MemoryProductRepository {
    rows: Arc<Mutex<Vec<Product>>>,
    next_id: Arc<Mutex<i64>>,
}

impl MemoryProductRepository {
    /// The rows reads see, by primary key.
    fn visible(&self) -> Vec<Product> {
        let mut rows: Vec<Product> = self.rows.lock().unwrap().iter().cloned().collect();
        rows.sort_by(|a, b| key_of(a).partial_cmp(&key_of(b)).unwrap_or(Ordering::Equal));
        rows
    }

    /// Keeps a row, in place of the one with its key.
    fn store(&self, entity: &Product) {
        let mut rows = self.rows.lock().unwrap();
        rows.retain(|row| key_of(row) != key_of(entity));
        rows.push(entity.clone());
    }
}

/// The key of a row, as a tuple of its key values.
fn key_of(row: &Product) -> (Option<i64>,) {
    (row.id,)
}

#[async_trait]
impl ProductRepository for MemoryProductRepository {
    async fn find_by_id(&self, id: i64) -> Result<Option<Product>, DomainError> {
        Ok(self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)))
    }

    async fn list(&self, after: Option<i64>, limit: u64) -> Result<CursorPage<Product, i64>, DomainError> {
        let after = after.map(|after| (Some(after),));
        let rows: Vec<_> = self
            .visible()
            .into_iter()
            .filter(|row| after.as_ref().is_none_or(|after| key_of(row).partial_cmp(after) == Some(Ordering::Greater)))
            .collect();
        let more = rows.len() as u64 > limit;
        let items: Vec<Product> = rows.into_iter().take(limit as usize).collect();
        let next = if more { items.last().map(|last| last.id.expect("id is set")) } else { None };
        Ok(CursorPage { items, next })
    }

    async fn list_by_category_id(&self, category_id: i64) -> Result<Vec<Product>, DomainError> {
        Ok(self.visible().into_iter().filter(|row| row.category_id.as_ref() == Some(&category_id)).collect())
    }

    async fn find_all_by_status(&self, status: String) -> Result<Vec<Product>, DomainError> {
        Ok(self.visible().into_iter().filter(|row| row.status.as_ref() == Some(&status)).collect())
    }

    async fn insert(&self, entity: Product) -> Result<Product, DomainError> {
        let mut entity = entity;
        entity.id = entity.id.or_else(|| {
            let mut next = self.next_id.lock().unwrap();
            *next += 1;
            Some(*next)
        });
        entity.version = entity.version.or_else(|| Some(1));
        self.store(&entity);
        Ok(entity)
    }

    async fn update(&self, entity: Product) -> Result<Product, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn delete(&self, entity: &Product) -> Result<(), DomainError> {
        self.rows.lock().unwrap().retain(|row| key_of(row) != key_of(entity));
        Ok(())
    }
}

