//! The service of the "tags" table.

use crate::common::CursorPage;
use crate::errors::{DomainError, FieldError};
use crate::tags::entity::Tag;
use crate::unit_of_work::UnitOfWork;
use std::sync::Arc;

/// The values of a Tag that change: fields left None keep their value; Some(None) empties one.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct TagChanges {
    pub label: Option<Option<String>>,
}

/// Operations on tags. Each write runs in a transaction of its own.
pub struct TagService {
    unit_of_work: Arc<dyn UnitOfWork>,
}

impl TagService {
    pub fn new(unit_of_work: Arc<dyn UnitOfWork>) -> Self {
        Self { unit_of_work }
    }

    /// Stores a new Tag after checking it.
    pub async fn create_tag(&self, tag: Tag) -> Result<Tag, DomainError> {
        let values = Values { label: tag.label.map(Some) };
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        check_values(uow, &values, None).await?;
        let mut entity = Tag::default();
        apply_values(&mut entity, &values);
        let created = uow.tags().insert(entity).await?;
        transaction.commit().await?;
        Ok(created)
    }

    /// The Tag with this key; NotFound when there is none.
    pub async fn get_tag(&self, id: i64) -> Result<Tag, DomainError> {
        find(self.unit_of_work.as_ref(), id).await
    }

    /// A page of tags after the key after (None for the first page), by primary key.
    pub async fn list_tags(&self, after: Option<i64>, limit: u64) -> Result<CursorPage<Tag, i64>, DomainError> {
        self.unit_of_work.tags().list(after, limit).await
    }

    /// Changes the given values of a Tag.
    pub async fn update_tag(&self, id: i64, changes: TagChanges) -> Result<Tag, DomainError> {
        let values = given(changes);
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let mut current = find(uow, id).await?;
        check_values(uow, &values, Some(&current)).await?;
        apply_values(&mut current, &values);
        let updated = uow.tags().update(current).await?;
        transaction.commit().await?;
        Ok(updated)
    }

    /// Deletes a Tag.
    pub async fn delete_tag(&self, id: i64) -> Result<(), DomainError> {
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let current = find(uow, id).await?;
        uow.tags().delete(&current).await?;
        transaction.commit().await?;
        Ok(())
    }
}

/// The values a create or an update gives, by field: None when not given, Some(None) when given empty.
#[derive(Default)]
struct Values {
    label: Option<Option<String>>,
}

/// Checks the values against the rules of the "tags" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(_uow: &dyn UnitOfWork, values: &Values, current: Option<&Tag>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.label.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.label.is_some() {
                errors.push(FieldError::new("label", "is required"));
            }
        }
        Some(value) => {
            if value.chars().count() > 30 {
                errors.push(FieldError::new("label", "is longer than 30 characters"));
            }
        }
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "Tag".to_string(), errors })
    }
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&Tag>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    Ok(())
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut Tag, values: &Values) {
    if let Some(value) = &values.label {
        entity.label = value.clone();
    }
}

/// The values an update gives, by field.
fn given(changes: TagChanges) -> Values {
    Values { label: changes.label }
}

/// The Tag with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, id: i64) -> Result<Tag, DomainError> {
    uow.tags().find_by_id(id).await?.ok_or_else(|| DomainError::not_found("Tag", id))
}

