//! The repository of the "categories" table, against the test database.

use seaorm_mysql_decided_cursor_by_table_optional::unit_of_work::UnitOfWork;
use super::{database, factories};

#[tokio::test]
async fn is_stored_and_read_back() {
    let (_turn, uow) = database::open().await;
    let stored = factories::add_category(&uow, 1).await;
    let found = uow.categories().find_by_id(stored.id.expect("id is set")).await.expect("a read").expect("the row");
    assert_eq!(stored.id, found.id);
    assert!(uow.categories().find_by_name(stored.name.clone().expect("name is set")).await.expect("a read").is_some());
}

#[tokio::test]
async fn lists_rows_by_key() {
    let (_turn, uow) = database::open().await;
    factories::add_category(&uow, 1).await;
    factories::add_category(&uow, 2).await;
    let first = uow.categories().list(None, 1).await.expect("a page");
    assert_eq!(1, first.items.len());
    assert!(first.next.is_some());
    let second = uow.categories().list(first.next, 1).await.expect("a page");
    assert_eq!(1, second.items.len());
    assert!(second.next.is_none());
}

#[tokio::test]
async fn is_deleted() {
    let (_turn, uow) = database::open().await;
    let stored = factories::add_category(&uow, 1).await;
    uow.categories().delete(&stored).await.expect("a delete");
    assert!(uow.categories().find_by_id(stored.id.expect("id is set")).await.expect("a read").is_none());
}

