        status: Some(format!("status-{n}")),
        version: Some(n),
        deleted_at: Some(chrono::NaiveDate::from_ymd_opt(2026, 1, (n % 28 + 1) as u32).expect("a date").and_hms_opt(12, 0, 0).expect("a time").and_utc().fixed_offset()),
        ..Default::default()
    }
}

